y-head input{width:90px;padding:8px;border:1px solid #c8dbe7;border-radius:7px}.record-table td,.record-table th{text-align:center}.record-table td:nth-child(-n+3),.record-table th:nth-child(-n+3){text-align:left}.leave-chip{font-weight:800;color:#805600}.on-duty{color:#08765b;font-weight:800}@media(max-width:950px){.encode-grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:600px){.encode-grid{grid-template-columns:1fr}.encode-grid .wide{grid-column:auto}}
