<script defer src="../public/js/nursync-ui.js?v=4"></script></head><body class="module-ui"><?php include '../includes/employee_documents_sidebar.php';?><main class="ed-expiring-main"><header class="page-head"><div><h1><i class="fa-solid fa-pen-to-square"></i> Encode Attendance &amp; Leave</h1><p>Record one employee duty or leave entry. Late minutes are calculated automatically.</p></div></header><?php if($error):?><div class="alert alert-danger"><?=h($error)?></div><?php endif;?><?php if($success):?><div class="alert alert-success"><?=h($success)?></div><?php endif;?>
<section class="panel"><form method="post" id="attendanceForm"><?=csrfField()?><input type="hidden" name="action" value="save_attendance_record"><input type="hidden" name="return_view" value="attendance_leave_encode"><div class="encode-grid">
<div class="form-field">Employee Name *<div class="employee-picker" id="employeePickerWrap"><i class="fa-solid fa-magnifying-glass"></i><input type="search" id="employeePicker" placeholder="Search name, ID, or department" autocomplete="off" required aria-haspopup="listbox" aria-expanded="false"><button class="employee-picker-toggle" type="button" aria-label="Show employees"><i class="fa-solid fa-chevron-down"></i></button><input type="hidden" name="employee_id" id="employeeId"><div class="employee-dropdown" id="employeeDropdown" role="listbox"><?php foreach($employees as$employee):$employeeLabel=$employee['name'].' — '.($employee['employee_id']?:$employee['user_id']).' — '.str_replace('_',' ',$employee['department']??'');?><button type="button" class="employee-option" role="option" data-id="<?=$employee['user_id']?>" data-label="<?=h($employeeLabel)?>" data-search="<?=h(strtolower($employeeLabel))?>"><span class="employee-option-avatar"><i class="fa-solid fa-user-nurse"></i></span><span><strong><?=h($employee['name'])?></strong><small><?=h(($employee['employee_id']?:$employee['user_id']).' · '.str_replace('_',' ',$employee['department']??''))?></small></span></button><?php endforeach;?><div class="employee-empty" hidden>No matching employee found.</div></div></div></div>
<label>What will you encode? *<select name="record_type" id="recordType" required><option value="">Select record type</option><option value="LATE">Late</option><option value="LEAVE">Leave</option></select></label>
<label>Record Date *<input type="date" name="record_date" max="<?=date('Y-m-d')?>" value="<?=date('Y-m-d')?>" required></label>
<label class="conditional-field late-field" hidden>Duty Schedule *<select name="duty_schedule" id="dutySchedule"><option value="">Select schedule</option><option value="06:00-18:00">6:00 AM – 6:00 PM</option><option value="18:00-06:00">6:00 PM – 6:00 AM</option><option value="06:00-14:00">6:00 AM – 2:00 PM</option><option value="14:00-22:00">2:00 PM – 10:00 PM</option><option value="22:00-06:00">10:00 PM – 6:00 AM</option><option value="07:00-18:00">7:00 AM – 6:00 PM</option><option value="08:00-17:00">8:00 AM – 5:00 PM</option></select></label>
<label class="conditional-field late-field" hidden>Actual Time In *<input type="time" name="actual_time_in" id="actualTime"></label>
<label class="conditional-field leave-field" hidden>Type of Leave *<select name="leave_type" id="leaveType"><option value="">Select leave type</option><option>VACATION LEAVE</option><option>SICK LEAVE</option><option>SPECIAL PRIVILEGE LEAVE</option><option>WELLNESS LEAVE</option><option>CALAMITY LEAVE</option></select></label>
<label class="conditional-field late-field" hidden>Calculated Late Minutes<div class="late-result" id="lateResult">0 min</div></label><label class="wide">Remarks<input type="text" name="remarks" maxlength="255" placeholder="Optional remarks"></label></div><div class="form-actions"><button class="btn green" type="submit"><i class="fa-solid fa-floppy-disk"></i> Save Record</button></div></form></section>
<section class="panel"><div class="history-head"><div><h2>Encoded Records</h2><p>Latest records for <?=$leaveYear?>.</p></div><form method="get"><input type="hidden" name="view" value="attendance_leave_encode"><input type="number" name="year" min="2000" max="2100" value="<?=$leaveYear?>"><button class="btn light">View</button></form></div><div class="table-wrap"><table class="table record-table"><thead><tr><th>Date</th><th>Employee</th><th>Department</th><th>Duty</th><th>Time In</th><th>Late</th><th>Attendance / Leave</th><th>Remarks</th></tr></thead><tbody><?php foreach($attendanceRecords as$record):?><tr><td><?=date('M d, Y',strtotime($record['record_date']))?></td><td><strong><?=h($record['employee_name'])?></strong></td><td><?=h(str_replace('_',' ',$record['department']??''))?></td><td><?=h($record['duty_schedule'])?></td><td><?=$record['actual_time_in']?date('g:i A',strtotime($record['actual_time_in'])):'—'?></td><td><strong><?=(int)$record['late_minutes']?> min</strong></td><td><?php if($record['leave_type']):?><span class="leave-chip"><?=h($record['leave_type'])?></span><?php else:?><span class="on-duty">ON DUTY</span><?php endif;?></td><td><?=h($record['remarks']?:'—')?></td></tr><?php endforeach;?><?php if(!$attendanceRecords):?><tr><td colspan="8" class="empty">No attendance or leave records encoded for this year.</td></tr><?php endif;?></tbody></table></div></section></main>
<script>(()=>{const form=document.getElementById('attendanceForm'),recordType=document.getElementById('recordType'),schedule=document.getElementById('dutySchedule'),actual=document.getElementById('actualTime'),leave=document.getElementById('leaveType'),result=document.getElementById('lateResult'),lateFields=[...document.querySelectorAll('.late-field')],leaveFields=[...document.querySelectorAll('.leave-field')],wrap=document.getElementById('employeePickerWrap'),employeePicker=document.getElementById('employeePicker'),employeeId=document.getElementById('employeeId'),dropdown=document.getElementById('employeeDropdown'),toggle=wrap.querySelector('.employee-picker-toggle'),options=[...dropdown.querySelectorAll('.employee-option')],empty=dropdown.querySelector('.employee-empty');let active=-1;function open(){wrap.classList.add('open');employeePicker.setAttribute('aria-expanded','true')}function close(){wrap.classList.remove('open');employeePicker.setAttribute('aria-expanded','false');active=-1;options.forEach(option=>option.classList.remove('active'))}function filter(){const query=employeePicker.value.trim().toLowerCase();let visible=0;employeeId.value='';employeePicker.setCustomValidity('Please select an employee from the list.');options.forEach(option=>{const show=!query||option.dataset.search.includes(query);option.hidden=!show;if(show)visible++});empty.hidden=visible>0;open()}function choose(option){employeePicker.value=option.dataset.label;employeeId.value=option.dataset.id;employeePicker.setCustomValidity('');close()}function visibleOptions(){return options.filter(option=>!option.hidden)}function move(step){const visible=visibleOptions();if(!visible.length)return;active=(active+step+visible.length)%visible.length;options.forEach(option=>option.classList.remove('active'));visible[active].classList.add('active');visible[active].scrollIntoView({block:'nearest'})}function updateLate(){if(!schedule.value||!actual.value){result.textContent='0 min';result.classList.remove('late');return}const start=schedule.value.slice(0,5).split(':').map(Number),time=actual.value.split(':').map(Number),minutes=Math.max(0,(time[0]*60+time[1])-(start[0]*60+start[1]));result.textContent=minutes+' min';result.classList.toggle('late',minutes>0)}function updateType(){const isLate=recordType.value==='LATE',isLeave=recordType.value==='LEAVE';lateFields.forEach(field=>field.hidden=!isLate);leaveFields.forEach(field=>field.hidden=!isLeave);schedule.required=isLate;actual.required=isLate;leave.required=isLeave;if(!isLate){schedule.value='';actual.value='';result.textContent='0 min';result.classList.remove('late')}if(!isLeave)leave.value=''}employeePicker.addEventListener('focus',open);employeePicker.addEventListener('input',filter);employeePicker.addEventListener('keydown',event=>{if(event.key==='ArrowDown'){event.preventDefault();move(1)}else if(event.key==='ArrowUp'){event.preventDefault();move(-1)}else if(event.key==='Enter'&&active>=0){event.preventDefault();choose(visibleOptions()[active])}else if(event.key==='Escape')close()});toggle.addEventListener('click',()=>{wrap.classList.contains('open')?close():(open(),employeePicker.focus())});options.forEach(option=>option.addEventListener('click',()=>choose(option)));document.addEventListener('click',event=>{if(!wrap.contains(event.target))close()});form.addEventListener('submit',()=>employeePicker.setCustomValidity(employeeId.value?'':'Please select an employee from the list.'));recordType.addEventListener('change',updateType);schedule.addEventListener('change',updateLate);actual.addEventListener('input',updateLate);updateType()})();</script></body></html>
